export const MOVES={punch:{startup:.12,active:.13,recovery:.25,damage:55,range:1.35,width:.92,height:.95,knockback:2.2,stun:.4,cooldown:.48},kick:{startup:.23,active:.16,recovery:.34,damage:82,range:1.62,width:1.05,height:.75,knockback:3.2,stun:.5,cooldown:.68},special:{startup:.32,active:.2,recovery:.5,damage:145,range:2.55,width:1.7,height:1.35,knockback:4.4,stun:.68,cooldown:1.8}};
export class FighterState { constructor(id,x){this.id=id;this.x=x;this.z=0;this.y=0;this.vx=0;this.vy=0;this.health=1000;this.energy=0;this.facing=id==='pedro'?1:-1;this.state='idle';this.timer=0;this.stun=0;this.cooldowns={punch:0,kick:0,special:0};this.attack=null;this.hitThisMove=false;this.combo=0;this.comboTimer=0;this.block=false;this.crouch=false;this.dead=false;} }
export function beginAttack(f,kind){const m=MOVES[kind];if(f.dead||f.stun>0||f.attack||f.cooldowns[kind]>0||!m)return false;f.attack={kind,time:0,move:m,hit:false};f.hitThisMove=false;f.state=kind;f.timer=0;f.cooldowns[kind]=m.cooldown;return true;}
export function hitbox(f){if(!f.attack)return null;const {move,time}=f.attack;if(time<move.startup||time>move.startup+move.active)return null;const cx=f.x+f.facing*(move.range*.52);return {left:cx-move.width/2,right:cx+move.width/2,bottom:f.y+.55,top:f.y+move.height+.55};}
export function hurtbox(f){return {left:f.x-.36,right:f.x+.36,bottom:f.y,top:f.y+(f.crouch?.92:1.8)};}
export function overlaps(a,b){return a&&b&&a.left<b.right&&a.right>b.left&&a.bottom<b.top&&a.top>b.bottom;}
export function resolveAttack(a,b){const box=hitbox(a);if(!box||a.attack.hit||b.dead||!overlaps(box,hurtbox(b))||Math.abs(a.z-b.z)>.48)return false;a.attack.hit=true;const guarding=b.block&&b.facing===-a.facing;if(guarding){b.state='block';b.stun=.2;b.vx=a.facing*.6;b.energy=Math.min(100,b.energy+4);return 'block';}const m=a.attack.move;b.health=Math.max(0,b.health-m.damage);b.state=b.health?'hit':'ko';b.stun=m.stun;b.vx=a.facing*m.knockback;b.energy=Math.min(100,b.energy+Math.min(18,m.damage/8));b.dead=b.health===0;a.combo++;a.comboTimer=1.35;return 'hit';}
